#!/usr/bin/env python3
"""Full verification: ping tests from all hosts."""
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

HOSTS = {
    "B1-PC1": {"mgmt": "192.168.122.31", "lab": "10.1.1.10", "guest": False},
    "B1-PC2": {"mgmt": "192.168.122.32", "lab": "10.1.1.11", "guest": False},
    "B2-PC1": {"mgmt": "192.168.122.33", "lab": "10.1.2.10", "guest": False},
    "B2-PC2": {"mgmt": "192.168.122.34", "lab": "10.1.2.11", "guest": False},
    "B3-PC1": {"mgmt": "192.168.122.35", "lab": "10.1.3.10", "guest": False},
    "B3-PC2": {"mgmt": "192.168.122.36", "lab": "10.1.3.11", "guest": False},
    "B4-PC1": {"mgmt": "192.168.122.37", "lab": "10.2.1.10", "guest": False},
    "B4-PC2": {"mgmt": "192.168.122.38", "lab": "10.2.1.11", "guest": False},
    "B4-PC3": {"mgmt": "192.168.122.39", "lab": "10.2.2.10", "guest": True},
    "B4-PC4": {"mgmt": "192.168.122.40", "lab": "10.2.2.11", "guest": True},
}

def ping_from(src_name, targets):
    """Ping all targets from src, return dict of target_ip -> pass/fail."""
    src = HOSTS[src_name]
    results = {}
    try:
        conn = ConnectHandler(host=src["mgmt"], device_type="linux", username="root", password="alpine")
        for tgt_ip, tgt_name in targets:
            out = conn.send_command(f"ping -c 2 -W 2 {tgt_ip}", read_timeout=15)
            success = "bytes from" in out or " 0% packet loss" in out
            results[f"{src_name} -> {tgt_name} ({tgt_ip})"] = "PASS" if success else "FAIL"
        conn.disconnect()
    except Exception as e:
        for tgt_ip, tgt_name in targets:
            results[f"{src_name} -> {tgt_name} ({tgt_ip})"] = f"ERROR: {e}"
    return results

def main():
    time.sleep(10)

    all_results = {}
    host_names = list(HOSTS.keys())

    # Build target lists for each host
    tasks = []
    for src_name in host_names:
        targets = []
        # Other hosts
        for tgt_name, tgt_info in HOSTS.items():
            if tgt_name != src_name:
                targets.append((tgt_info["lab"], tgt_name))
        # Internet targets
        targets.append(("8.8.8.8", "ISP-A-lo"))
        targets.append(("1.1.1.1", "ISP-B-lo"))
        tasks.append((src_name, targets))

    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = {pool.submit(ping_from, src, tgts): src for src, tgts in tasks}
        for f in as_completed(futures):
            results = f.result()
            all_results.update(results)

    # Print results organized
    # Non-guest to non-guest (should all PASS)
    non_guest = [n for n, i in HOSTS.items() if not i["guest"]]
    guest = [n for n, i in HOSTS.items() if i["guest"]]

    print("=== NON-GUEST TO NON-GUEST (expect PASS) ===")
    fails = []
    passes = 0
    for src in non_guest:
        for tgt in non_guest:
            if src == tgt:
                continue
            key = f"{src} -> {tgt} ({HOSTS[tgt]['lab']})"
            result = all_results.get(key, "MISSING")
            if result != "PASS":
                fails.append(f"  {key}: {result}")
            else:
                passes += 1
    print(f"  {passes} PASS, {len(fails)} FAIL")
    for f in fails:
        print(f)

    print("\n=== GUEST TO GUEST (expect PASS) ===")
    for src in guest:
        for tgt in guest:
            if src == tgt:
                continue
            key = f"{src} -> {tgt} ({HOSTS[tgt]['lab']})"
            print(f"  {key}: {all_results.get(key, 'MISSING')}")

    print("\n=== GUEST <-> NON-GUEST (expect FAIL - policy) ===")
    unexpected = []
    expected_fails = 0
    for src in guest:
        for tgt in non_guest:
            key = f"{src} -> {tgt} ({HOSTS[tgt]['lab']})"
            result = all_results.get(key, "MISSING")
            if result == "FAIL":
                expected_fails += 1
            else:
                unexpected.append(f"  {key}: {result} (expected FAIL)")
    for src in non_guest:
        for tgt in guest:
            key = f"{src} -> {tgt} ({HOSTS[tgt]['lab']})"
            result = all_results.get(key, "MISSING")
            if result == "FAIL":
                expected_fails += 1
            else:
                unexpected.append(f"  {key}: {result} (expected FAIL)")
    print(f"  {expected_fails} correctly FAIL, {len(unexpected)} unexpected")
    for u in unexpected:
        print(u)

    print("\n=== INTERNET REACHABILITY (expect PASS) ===")
    for src in host_names:
        for tgt in ["ISP-A-lo", "ISP-B-lo"]:
            ip = "8.8.8.8" if tgt == "ISP-A-lo" else "1.1.1.1"
            key = f"{src} -> {tgt} ({ip})"
            print(f"  {key}: {all_results.get(key, 'MISSING')}")

if __name__ == "__main__":
    main()

